    "sys.welcome": { text: "नमस्कार, मी दृष्टी. तुमच्या आजूबाजूला काय आहे ते मी सांगेन.", en: "Hello, I am Drishti. I will tell you what is around you.", asset: null },
    "sys.cane": { text: "दृष्टी तुमच्या काठीसोबत काम करते, तिच्या जागी नाही.", en: "Drishti works with your cane, not instead of it.", asset: null },
    "sys.tutorial_1": { text: "गाड्या, खुर्च्या किंवा माणसे असे समोरचे मी आपोआप सांगेन.", en: "I will announce things ahead on my own, like cars, chairs or people.", asset: null },
    "sys.tutorial_2": { text: "काही विचारायचे असल्यास दृष्टी म्हणा, मग तुमचा प्रश्न विचारा. किंवा स्क्रीन दाबून धरा, बोला, मग सोडा.", en: "To ask something, say Drishti, then ask your question. Or press and hold the screen, speak, then let go.", asset: null },
    "sys.tutorial_3": { text: "उदाहरणार्थ विचारा, समोर काय आहे, किंवा हे वाच.", en: "For example, ask: what is ahead, or read this.", asset: null },
    "sys.tutorial_4": { text: "एखाद्याला लक्षात ठेवण्यासाठी म्हणा, याला राहुल नावाने सेव्ह कर.", en: "To remember someone, say: save this as Rahul.", asset: null },
    "sys.tutorial_5": { text: "मला थांबवण्यासाठी म्हणा, थांब. भाषा बदलण्यासाठी म्हणा, इंग्रजीत बोल.", en: "To stop me, say stop. To change language, say Hindi mein bolo, or Tamil mein bolo.", asset: null },
    "sys.unknown_person": { text: "समोर एक अनोळखी व्यक्ती आहे", en: "An unknown person is ahead", asset: null },
    "sys.no_internet": { text: "इंटरनेट नाही", en: "No internet", asset: null },
    "sys.internet_lost": { text: "इंटरनेट गेले, सूचना चालू आहेत", en: "Internet lost. Alerts are still on.", asset: null },
    "sys.internet_back": { text: "इंटरनेट परत आले", en: "Internet is back", asset: null },
    "sys.camera_blocked": { text: "कॅमेऱ्याला स्पष्ट दिसत नाही", en: "The camera can't see clearly", asset: null },
    "sys.step_drop": { text: "समोर पायरी किंवा खड्डा आहे", en: "Step or drop ahead", asset: null },
    "sys.looking": { text: "पाहते आहे", en: "Let me look", asset: null },
    "sys.didnt_hear": { text: "समजले नाही, पुन्हा सांगा", en: "Sorry, I didn't catch that. Please say it again.", asset: null },
    "sys.answer_failed": { text: "आत्ता उत्तर मिळाले नाही, पुन्हा विचारा", en: "I couldn't get an answer. Please ask again.", asset: null },
    "sys.nothing_to_repeat": { text: "पुन्हा सांगण्यासारखे काही नाही", en: "There is nothing to repeat", asset: null },
    "sys.quiet_on": { text: "शांत मोड चालू. फक्त वाहने सांगेन.", en: "Quiet mode on. I'll only announce vehicles.", asset: null },
    "sys.quiet_off": { text: "शांत मोड बंद", en: "Quiet mode off", asset: null },
    "sys.no_one_here": { text: "आत्ता ओळखीचे कोणी दिसत नाही", en: "I don't see anyone you've saved right now", asset: null },
    "sys.ask_name": { text: "नाव सांगा", en: "Please say the name", asset: null },
    "sys.consent": { text: "तुम्ही सेव्ह होण्यास तयार आहात का?", en: "Do you agree to be saved?", asset: null },
    "sys.enroll_hold": { text: "तीन सेकंद कॅमेऱ्याकडे पाहा", en: "Please face the camera for three seconds", asset: null },
    "sys.enroll_no_face": { text: "चेहरा स्पष्ट दिसला नाही, पुन्हा प्रयत्न करा", en: "I couldn't see the face clearly. Please try again.", asset: null },
    "sys.enroll_cancelled": { text: "ठीक आहे, सेव्ह केले नाही", en: "Okay, not saved", asset: null },
